"use strict";(self.webpackChunkdocs_site=self.webpackChunkdocs_site||[]).push([["459"],{1662(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/d-cron/docs/intro","label":"Overview","docId":"intro","unlisted":false},{"type":"link","href":"/d-cron/docs/installation","label":"Installation","docId":"installation","unlisted":false},{"type":"link","href":"/d-cron/docs/quickstart","label":"Quickstart","docId":"quickstart","unlisted":false},{"type":"category","label":"Features","collapsed":false,"items":[{"type":"link","href":"/d-cron/docs/architecture/advisory-locks","label":"Core Architecture","docId":"architecture/advisory-locks","unlisted":false},{"type":"link","href":"/d-cron/docs/architecture/fencing-tokens","label":"Split-Brain & Fencing","docId":"architecture/fencing-tokens","unlisted":false},{"type":"link","href":"/d-cron/docs/guides/execution-safety","label":"Execution Safety & Retries","docId":"guides/execution-safety","unlisted":false},{"type":"link","href":"/d-cron/docs/guides/overlap-missed-runs","label":"Overlap & Missed Runs","docId":"guides/overlap-missed-runs","unlisted":false},{"type":"link","href":"/d-cron/docs/guides/history-store","label":"Execution History Store","docId":"guides/history-store","unlisted":false},{"type":"link","href":"/d-cron/docs/guides/observability","label":"Observability & Dashboard","docId":"guides/observability","unlisted":false},{"type":"link","href":"/d-cron/docs/production/kubernetes","label":"Production & Kubernetes","docId":"production/kubernetes","unlisted":false}],"collapsible":true,"href":"/d-cron/docs/features"},{"type":"link","href":"/d-cron/docs/api/dcron","label":"API Reference","docId":"api/dcron","unlisted":false},{"type":"link","href":"/d-cron/docs/troubleshooting","label":"Troubleshooting","docId":"troubleshooting","unlisted":false},{"type":"link","href":"/d-cron/docs/security","label":"Security","docId":"security","unlisted":false},{"type":"link","href":"/d-cron/docs/contributing","label":"Contributing","docId":"contributing","unlisted":false}]},"docs":{"api/dcron":{"id":"api/dcron","title":"API Reference","description":"Complete API reference for d-cron core packages: dcron, executor, metrics, and otel.","sidebar":"docsSidebar"},"architecture/advisory-locks":{"id":"architecture/advisory-locks","title":"Core Architecture","description":"d-cron provides safe, single-leader cron-style job scheduling across an arbitrary number of horizontally-scaled application replicas using only PostgreSQL Session-Bound Advisory Locks.","sidebar":"docsSidebar"},"architecture/fencing-tokens":{"id":"architecture/fencing-tokens","title":"Split-Brain & Fencing Tokens","description":"In distributed systems, GC pauses, heavy OS swapping, or temporary network partitions can cause a node to experience a split-brain state: a node thinks it is still the leader while a new leader has already been elected.","sidebar":"docsSidebar"},"contributing":{"id":"contributing","title":"Contributing","description":"Thank you for your interest in contributing to d-cron! We welcome contributions from the community and value every contributor, whether you are fixing a bug, adding a feature, improving documentation, or reporting an issue.","sidebar":"docsSidebar"},"guides/execution-safety":{"id":"guides/execution-safety","title":"Execution Safety, Panic Recovery & Retries","description":"Production background job engines must be resilient against runtime panics, unhandled errors, and external timeouts. d-cron provides built-in safety mechanics to prevent crash cascading and ensure reliable task execution.","sidebar":"docsSidebar"},"guides/history-store":{"id":"guides/history-store","title":"Audit & History Store","description":"By default, d-cron operates with zero database tables. When compliance, auditing, missed-run catch-up, or dashboard monitoring requires durable tracking, d-cron provides an opt-in durable execution history store backed by PostgreSQL.","sidebar":"docsSidebar"},"guides/observability":{"id":"guides/observability","title":"Observability & Dashboard","description":"d-cron provides deep observability across your distributed cron cluster, including an embedded Web Dashboard UI, Prometheus metrics, OpenTelemetry distributed tracing, webhook alert hooks, and an HTTP REST Admin API.","sidebar":"docsSidebar"},"guides/overlap-missed-runs":{"id":"guides/overlap-missed-runs","title":"Overlap & Missed Run Policies","description":"In production environments, a long-running batch job may take longer than its scheduled trigger interval, or an application deployment/restart may cause a scheduled trigger time to be missed.","sidebar":"docsSidebar"},"installation":{"id":"installation","title":"Installation & Setup","description":"d-cron is an embeddable Go library with zero external daemon dependencies. Installing and configuring it into an existing or new Go application requires minimal steps.","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"Introduction to d-cron","description":"d-cron is a high-performance, embeddable Go library that provides safe, coordinated cron-style job scheduling across an arbitrary number of application container replicas \u2014 using only the PostgreSQL database your application already operates.","sidebar":"docsSidebar"},"production/kubernetes":{"id":"production/kubernetes","title":"Production & Kubernetes","description":"d-cron is built natively for horizontal scaling in containerized production environments. Because coordination occurs at the database layer via PostgreSQL advisory locks, deployments require no custom Kubernetes CRDs, no statefulsets, and no RBAC permissions.","sidebar":"docsSidebar"},"quickstart":{"id":"quickstart","title":"Quickstart","description":"This guide demonstrates how to install d-cron, integrate it into a Go application with PostgreSQL, and configure cron schedules.","sidebar":"docsSidebar"},"security":{"id":"security","title":"Security","description":"d-cron takes security, isolation, and data integrity seriously. This page outlines how to report security issues and describes the defensive security practices engineered into the library.","sidebar":"docsSidebar"},"troubleshooting":{"id":"troubleshooting","title":"Troubleshooting","description":"This page provides solutions for common issues encountered when integrating or deploying d-cron.","sidebar":"docsSidebar"}}}}')}}]);